 1	method twoSum(nums: array<int>, target: int) returns (i: int, j: int)
 2	  requires nums.Length > 1
 3	  requires exists i,j::0 <= i < j < nums.Length &&  nums[i] + nums[j] == target
 4	  ensures 0 <= i < j < nums.Length && nums[i] + nums[j] == target
 5	  ensures forall ii,jj:: (0 <= ii < i && ii < jj < nums.Length)  ==> nums[ii] + nums[jj] != target
 6	  ensures forall jj:: i < jj < j ==> nums[i] + nums[jj] != target
 7	{
 8	  var n := nums.Length;
 9	  i := 0;
10	  j := 1;
11	  while i < n - 1
12	    invariant 0 <= i < j <= n
13	    invariant forall ii, jj :: 0 <= ii < i && ii < jj < n ==> nums[ii] + nums[jj] != target
14	  {
15	    j := i + 1;
16	    while j < n
17	      invariant 0 <= i < j <= (n) + 1
18	      invariant forall jj :: i < jj < j ==> nums[i] + nums[jj] != target
19	    {
20	      if nums[i] + nums[j] == target {
21	        return;
22	      }
23	      j := j + 1;
24	    }
25	
26	    i := i + 1;
27	  }
28	}

